"use client";

import { useState } from "react";
import { Loader2 } from "lucide-react";
import { api, pick, rowsOf, text } from "@/lib/api";
import { useApi } from "@/lib/use-api";
import { Button, Field, Input, Select, Textarea } from "@/components/ui";
import { Modal, useToast } from "@/components/interactive";

/** One building name per line → trimmed, de-duplicated list. */
export const parseBuildings = (s: string) => [...new Set(s.split("\n").map((b) => b.trim()).filter(Boolean))];

/** Textarea for a list of building names; the codes are generated by the server from the code prefix. */
export function BuildingNamesField({ value, onChange, prefix }: { value: string; onChange: (v: string) => void; prefix: string }) {
  const n = parseBuildings(value).length;
  const p = prefix.trim().toUpperCase() || "PREFIX";
  return (
    <Field label="Buildings" required className="sm:col-span-2" hint={`One per line · ${n} building${n === 1 ? "" : "s"} · codes are generated as ${p}-…`}>
      <Textarea value={value} onChange={(e) => onChange(e.target.value)} placeholder={"Tower-A\nBasement-1\nPump Room"} className="min-h-32 font-mono text-[13px]" />
    </Field>
  );
}

const EMPTY = { creator_user_id: "", admin_user_id: "", vendor_id: "", code_prefix: "", city: "", buildings: "" };

const userOptions = (rows: unknown) =>
  rowsOf(rows).map((u) => ({ id: text(pick(u, "id", "user_id"), ""), label: `${text(pick(u, "name", "user_name"))} · ${text(pick(u, "email"), "")}` })).filter((u) => u.id);

/** Adds buildings to an existing client organisation (addOrgBuildings), identified by its Complaint Creator and Client Admin. */
export function AddOrgBuildingsModal({ open, onClose, onCreated }: { open: boolean; onClose: () => void; onCreated?: () => void }) {
  const [form, setForm] = useState(EMPTY);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const toast = useToast();
  const vendors = useApi(() => api.getVendors(), [open]);
  const creators = useApi(() => api.getAllUsers({ role: "client", page: 1, limit: 100 }), [open]);
  const admins = useApi(() => api.getAllUsers({ role: "client_admin", page: 1, limit: 100 }), [open]);

  const set = (k: keyof typeof EMPTY) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const create = async () => {
    const f = form;
    const buildings = parseBuildings(f.buildings);
    if (!f.creator_user_id || !f.admin_user_id) return setFormError("Choose the organisation’s Complaint Creator and Client Admin.");
    if (!f.code_prefix.trim() || !f.city.trim()) return setFormError("Code prefix and city are required.");
    if (!buildings.length) return setFormError("Add at least one building.");
    setSaving(true);
    setFormError(null);
    try {
      await api.addOrgBuildings({
        creator_user_id: Number(f.creator_user_id),
        admin_user_id: Number(f.admin_user_id),
        vendor_id: f.vendor_id ? Number(f.vendor_id) : null,
        code_prefix: f.code_prefix.trim().toUpperCase(),
        city: f.city.trim(),
        buildings,
      });
      setForm(EMPTY);
      toast.show(`${buildings.length} building${buildings.length === 1 ? "" : "s"} added`);
      onCreated?.();
      onClose();
    } catch (e) {
      setFormError(e instanceof Error ? e.message : "Could not add the buildings.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <Modal
        open={open}
        onClose={onClose}
        title="Add buildings"
        description="Adds buildings to an existing client organisation. Its Complaint Creator and Client Admin get access straight away."
        size="lg"
        footer={
          <>
            <Button variant="secondary" onClick={onClose}>Cancel</Button>
            <Button onClick={create} disabled={saving}>{saving ? <Loader2 className="animate-spin" /> : null} Add buildings</Button>
          </>
        }
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Complaint Creator" required>
            <Select value={form.creator_user_id} onChange={set("creator_user_id")}>
              <option value="">{creators.loading ? "Loading…" : "Select creator"}</option>
              {userOptions(creators.data?.data).map((u) => <option key={u.id} value={u.id}>{u.label}</option>)}
            </Select>
          </Field>
          <Field label="Client Admin" required>
            <Select value={form.admin_user_id} onChange={set("admin_user_id")}>
              <option value="">{admins.loading ? "Loading…" : "Select admin"}</option>
              {userOptions(admins.data?.data).map((u) => <option key={u.id} value={u.id}>{u.label}</option>)}
            </Select>
          </Field>
          <Field label="Code prefix" required><Input value={form.code_prefix} onChange={set("code_prefix")} placeholder="e.g. RITES" className="uppercase" /></Field>
          <Field label="City" required><Input value={form.city} onChange={set("city")} placeholder="e.g. Kolkata" /></Field>
          <Field label="Primary vendor" className="sm:col-span-2">
            <Select value={form.vendor_id} onChange={set("vendor_id")}>
              <option value="">No vendor yet</option>
              {vendors.data?.map((v) => <option key={v.id} value={v.id}>{v.company_name}</option>)}
            </Select>
          </Field>
          <BuildingNamesField value={form.buildings} onChange={(buildings) => setForm((f) => ({ ...f, buildings }))} prefix={form.code_prefix} />
          {formError && <p role="alert" className="rounded-xl bg-rose-50 p-3 text-[13px] font-medium text-rose-700 sm:col-span-2">{formError}</p>}
        </div>
      </Modal>
      {toast.node}
    </>
  );
}
